class _ReconnectingStateLines:
    """Iterate newline-delimited state while transparently reopening USB EOFs."""

    def __init__(self, path: str, retry_s: float = 0.5):
        self.path = str(path)
        self.retry_s = max(0.05, float(retry_s))

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        return False

    def __iter__(self):
        last_error = ""
        last_error_log = 0.0
        while True:
            try:
                with open(self.path, "r", encoding="utf-8") as stream:
                    print(f"[state] connected to {self.path}", flush=True)
                    last_error = ""
                    last_error_log = 0.0
                    for line in stream:
                        yield line
                    print(f"[state] EOF from {self.path}; reopening", flush=True)
            except Exception as ex:
                detail = f"{type(ex).__name__}: {ex}"
                now = time.monotonic()
                # A deliberately hardware-free body still hosts the web UI.
                # Avoid filling its journal while retaining periodic evidence
                # and logging a changed failure immediately.
                if detail != last_error or now - last_error_log >= 10.0:
                    print(f"[state] unable to read {self.path}: {detail}; retrying", flush=True)
                    last_error = detail
                    last_error_log = now
            time.sleep(self.retry_s)

