def ensure_fifo_paths() -> None:
    """Ensure the fixed virtual-controller directory and FIFO paths exist."""
    os.makedirs(FIFO_DIR, mode=0o755, exist_ok=True)
    for path in (PUDDLE_FIFO_PATH, STEAM_FIFO_PATH):
        if os.path.exists(path):
            try:
                st = os.stat(path)
                if not stat.S_ISFIFO(st.st_mode):
                    os.unlink(path)
            except FileNotFoundError:
                pass
        if not os.path.exists(path):
            os.mkfifo(path, 0o666)
        try:
            os.chmod(path, 0o666)
        except Exception:
            pass


