# PuddleDuckStick exposes eight Linux joystick axes in the normal joydev
# ordering.  The FrSky radio's SBUS channel order is different: channels 2/3
# are the right stick while channel 4 is the left pot.  Keep that physical
# routing explicit instead of hiding it in a non-monotonic ABS-code table.
RC_AXIS_MAP = {
    0: e.ABS_X,
    1: e.ABS_Y,
    2: e.ABS_Z,
    3: e.ABS_RX,
    4: e.ABS_RY,
    5: e.ABS_RZ,
    6: e.ABS_THROTTLE,
    7: e.ABS_RUDDER,
}

# Zero-based raw SBUS channel -> PuddleDuckStick virtual joystick axis.
#
#   SBUS 0,1 : left stick       -> virtual axes 0,1
#   SBUS 2,3 : right stick      -> virtual axes 3,4
#   SBUS 4,5 : left/right pots  -> virtual axes 2,5
#   SBUS 6,7 : KyberPad/slider  -> virtual axes 6,7
PUDDLEDUCKSTICK_SBUS_TO_AXIS = (0, 1, 3, 4, 2, 5, 6, 7)


def puddleduckstick_axis_for_sbus_channel(channel: int) -> int:
    """Return the Linux joystick axis used for one zero-based SBUS channel."""
    channel = int(channel)
    if channel < 0 or channel >= len(PUDDLEDUCKSTICK_SBUS_TO_AXIS):
        raise ValueError(f"SBUS channel must be 0..{len(PUDDLEDUCKSTICK_SBUS_TO_AXIS) - 1}")
    return PUDDLEDUCKSTICK_SBUS_TO_AXIS[channel]


def puddleduckstick_axis_code_for_sbus_channel(channel: int) -> int:
    """Return the evdev ABS code emitted for one zero-based SBUS channel."""
    return RC_AXIS_MAP[puddleduckstick_axis_for_sbus_channel(channel)]

BTN_BASE      = 1000
MAX_BUTTONS   = 32

# XSR Sim reports full joystick range.
ABS_RANGE = (-32768, 32767)

INPUT_EVENT_FMT = "llHHi"
EV_SIZE = struct.calcsize(INPUT_EVENT_FMT)


# ---------------------------------------------------------------------
# Minimal OSC (no external deps)
#   - Supports: address + (int32/float32) arguments (including 2-float XY)
#   - Enough for TouchOSC control messages (e.g., /audio/volume 0.0..1.0)
# ---------------------------------------------------------------------
def _osc_pad4(b: bytes) -> bytes:
    return b + (b"\x00" * ((4 - (len(b) % 4)) % 4))

def _osc_pad4_str(s: str) -> bytes:
    return _osc_pad4(s.encode("utf-8") + b"\x00")

def osc_build_message_floats(address: str, *values: float) -> bytes:
    addr = _osc_pad4_str(address)
    tags = _osc_pad4_str("," + ("f" * len(values)))
    args = b"".join(struct.pack(">f", float(v)) for v in values)
    return addr + tags + args

def osc_build_message(address: str, value):
    # Back-compat: one int/float/string (bools become OSC booleans)
    return osc_build_message_args(address, value)

def osc_build_message_args(address: str, *values):
    """Build a single OSC message supporting i/f/s/T/F types."""
    addr = _osc_pad4_str(str(address))

    tag_chars = [","]
    args_blob = bytearray()

    for v in values:
        # OSC bool tags carry no payload.
        if isinstance(v, bool):
            tag_chars.append("T" if v else "F")
            continue

        # int32
        if isinstance(v, int):
            tag_chars.append("i")
            args_blob.extend(struct.pack(">i", int(v)))
            continue

        # float32
        if isinstance(v, float):
            tag_chars.append("f")
            args_blob.extend(struct.pack(">f", float(v)))
            continue

        # string
        if isinstance(v, str):
            tag_chars.append("s")
            args_blob.extend(_osc_pad4_str(v))
            continue

        # Fallbacks
        try:
            fv = float(v)
            tag_chars.append("f")
            args_blob.extend(struct.pack(">f", float(fv)))
        except Exception:
            sv = str(v)
            tag_chars.append("s")
            args_blob.extend(_osc_pad4_str(sv))

    tags = _osc_pad4_str("".join(tag_chars))
    return addr + tags + bytes(args_blob)

def _osc_read_str(data: bytes, offset: int):
    end = data.find(b"\x00", offset)
    if end < 0:
        return None, None
    s = data[offset:end].decode("utf-8", errors="replace")
    nxt = (end + 4) & ~3
    return s, nxt

def osc_parse_message(data: bytes):
    """Parse a single OSC message.

    Returns (address:str, tags:str, args:list) or (None,None,None) on failure.
    Supports i/f/s/T/F.
    """
    try:
        address, p = _osc_read_str(data, 0)
        if not address:
            return None, None, None

        tags, p = _osc_read_str(data, p)
        if not tags or not tags.startswith(","):
            return None, None, None

        args = []
        for t in tags[1:]:
            if t == "i":
                if p + 4 > len(data):
                    break
                args.append(struct.unpack(">i", data[p:p+4])[0]); p += 4
            elif t == "f":
                if p + 4 > len(data):
                    break
                args.append(struct.unpack(">f", data[p:p+4])[0]); p += 4
            elif t == "s":
                s, p2 = _osc_read_str(data, p)
                if s is None:
                    break
                args.append(s); p = p2
            elif t == "T":
                args.append(True)
            elif t == "F":
                args.append(False)
            else:
                break

        return address, tags, args
    except Exception:
        return None, None, None


def rc_value_to_abs(raw,
                    in_min=-1.0, in_max=1.0,
                    out_min=ABS_RANGE[0], out_max=ABS_RANGE[1]):
    if raw is None:
        return (out_min + out_max) // 2

    # Clamp
    if raw < in_min:
        raw = in_min
    if raw > in_max:
        raw = in_max

    span_in  = in_max - in_min
    span_out = out_max - out_min
    if span_in == 0:
        return (out_min + out_max) // 2
    return int(out_min + (raw - in_min) * span_out / span_in)


def neutral_axis_raw():
    # For typical signed joystick axes, the neutral/center value is 0.
    # Note: ranges like (-32768, 32767) have an arithmetic midpoint of -0.5,
    # which would floor to -1 and make "center" look non-zero.
    lo, hi = ABS_RANGE
    if lo < 0 < hi:
        return 0
    return (lo + hi) // 2


def axis_out_range(code: int) -> Tuple[int, int]:
    """Return (min,max) for a given ABS code."""
    return ABS_RANGE


def neutral_axis_raw_for_code(code: int) -> int:
    """Return a sensible 'neutral' raw value for a given ABS code."""
    return neutral_axis_raw()


def axis_value_to_abs(code: int, raw) -> int:
    """Convert a raw value (typically normalized float -1..1) to an evdev ABS value."""
    out_min, out_max = axis_out_range(code)
    if raw is None:
        return (out_min + out_max) // 2
    # Default: treat as normalized float in [-1, 1].
    return rc_value_to_abs(float(raw), out_min=out_min, out_max=out_max)


