class BaseSink:
    def emit_abs(self, code, value):
        raise NotImplementedError

    def emit_key(self, code, value):
        raise NotImplementedError

    def sync(self):
        raise NotImplementedError


class UInputSink(BaseSink):
    """
    Real kernel input device via /dev/uinput.
    """
    def __init__(
        self,
        device_name: str = PUDDLE_DEVICE_NAME,
        *,
        axis_map: Optional[Dict[int, int]] = None,
        btn_codes: Optional[List[int]] = None,
    ):
        if not os.path.exists("/dev/uinput"):
            raise RuntimeError("/dev/uinput does not exist")

        self.device_name = str(device_name)
        self.axis_map = axis_map if axis_map is not None else dict(RC_AXIS_MAP)
        self.btn_codes = btn_codes

        caps = self._build_capabilities()
        self.ui = UInput(caps, name=self.device_name, bustype=e.BUS_USB)
        print(f"[UInput] Created virtual device: {self.device_name} at {self.ui.devnode}")

    def _build_capabilities(self):
        capabilities = {}

        # Absolute axes
        abs_caps = []
        for _, code in (self.axis_map or {}).items():
            # (min, max, fuzz, flat)
            abs_caps.append((code, ABS_RANGE + (0, 0)))
        if abs_caps:
            capabilities[e.EV_ABS] = abs_caps

        # Buttons:
        #   - RC buttons: 0..7
        #   - Kyberpad/HW buttons: BTN_BASE+1 .. BTN_BASE+MAX_BUTTONS
        btn_codes = self.btn_codes
        if btn_codes is None:
            # Default:
            #   - RC buttons: 0..7
            #   - Kyberpad/HW buttons: BTN_BASE+1 .. BTN_BASE+MAX_BUTTONS
            btn_codes = [RC_BTN_FIRST + i for i in range(RC_BUTTON_COUNT)]
            btn_codes += [BTN_BASE + i for i in range(1, MAX_BUTTONS + 1)]
        if btn_codes:
            capabilities[e.EV_KEY] = list(btn_codes)
        return capabilities

    def emit_abs(self, code, value):
        self.ui.write(e.EV_ABS, code, value)

    def emit_key(self, code, value):
        self.ui.write(e.EV_KEY, code, value)

    def sync(self):
        self.ui.syn()


class FifoSink(BaseSink):
    """
    Fallback: write raw struct input_event records into a named pipe.
    We only write if there is a reader, using the same semantics as
    the C fifo_* helpers:
      - Non-blocking open (O_WRONLY|O_NONBLOCK)
      - ENXIO => no reader yet, drop this frame
      - EPIPE => reader vanished, close fd and drop this frame
      - EAGAIN => pipe full, drop this frame (latest-only)
    """
    def __init__(self, path=PUDDLE_FIFO_PATH, device_name: str = PUDDLE_DEVICE_NAME):
        self.path = path
        self.device_name = str(device_name)
        self.fd = -1
        self._ensure_fifo()
        print(f"[FIFO] Using FIFO {self.path} as virtual event device ({self.device_name})")

    def _ensure_fifo(self):
        # Ensure parent directory exists
        os.makedirs(os.path.dirname(self.path), exist_ok=True)

        if os.path.exists(self.path):
            st = os.stat(self.path)
            if not stat.S_ISFIFO(st.st_mode):
                raise RuntimeError(f"{self.path} exists but is not a FIFO")
        else:
            os.mkfifo(self.path)
            print(f"[FIFO] Created FIFO {self.path}")

    def _try_open(self):
        """
        Try to open the FIFO for writing, non-blocking.
        ENXIO means "no reader yet" so we just return False.
        """
        if self.fd >= 0:
            return True
        try:
            # O_WRONLY | O_NONBLOCK => don't block waiting for reader.
            self.fd = os.open(self.path, os.O_WRONLY | os.O_NONBLOCK)
            return True
        except OSError as e:
            if e.errno == errno.ENXIO:
                # No reader yet.
                return False
            # Other errors could be logged if you care.
            return False

    def _close_fd(self):
        if self.fd >= 0:
            os.close(self.fd)
            self.fd = -1

    def _write_event(self, etype, code, value):
        """
        Write one struct input_event. Drop silently if there's no reader
        or if the pipe is full, mirroring the C fifo_write_line behavior.
        """
        # Attempt to open FIFO if not already open
        if self.fd < 0 and not self._try_open():
            return  # no reader, nothing to do

        now = time.time()
        sec = int(now)
        usec = int((now - sec) * 1_000_000)
        data = struct.pack(INPUT_EVENT_FMT, sec, usec, etype, code, value)

        try:
            # Single write keeps event atomic (well below PIPE_BUF).
            os.write(self.fd, data)
        except OSError as e:
            if e.errno == errno.EPIPE:
                # Reader vanished; close and let next event try to reopen.
                self._close_fd()
                return
            if e.errno == errno.EAGAIN:
                # Pipe full -> drop to keep "latest-only" semantics.
                return
            # Other errors: drop as well, or log if you want.
            return

    def emit_abs(self, code, value):
        self._write_event(EV_ABS, code, value)

    def emit_key(self, code, value):
        self._write_event(EV_KEY, code, value)

    def sync(self):
        self._write_event(EV_SYN, SYN_REPORT, 0)


class InteractiveEventTapSink(BaseSink):
    """Mirror virtual-controller events into the web editor without consuming them."""

    def __init__(
        self,
        real_sink: BaseSink,
        event_hub: InteractiveControllerEventHub,
        device_name: str,
    ):
        self._real = real_sink
        self._event_hub = event_hub
        self._device_name = str(device_name)

    def _publish(self, event_type: int, code: int, value: int) -> None:
        try:
            self._event_hub.publish_evdev(
                self._device_name,
                int(event_type),
                int(code),
                int(value),
            )
        except Exception:
            # Mapping capture is optional and must never disrupt robot control.
            pass

    def emit_abs(self, code, value):
        self._real.emit_abs(code, value)
        self._publish(EV_ABS, code, value)

    def emit_key(self, code, value):
        self._real.emit_key(code, value)
        self._publish(EV_KEY, code, value)

    def sync(self):
        self._real.sync()


def create_sink_named(
    device_name: str,
    fifo_path: str,
    *,
    axis_map: Optional[Dict[int, int]] = None,
    btn_codes: Optional[List[int]] = None,
):
    """Create a virtual input sink.

    Preference order:
      1) /dev/uinput (real event device)
      2) named FIFO sink (fallback)
    """
    try:
        return UInputSink(device_name, axis_map=axis_map, btn_codes=btn_codes)
    except Exception as ex:
        print(f"[WARN] Failed to create uinput device '{device_name}': {ex}")
        print(f"[WARN] Falling back to FIFO virtual device at {fifo_path}.")
        return FifoSink(path=fifo_path, device_name=device_name)


def create_sink():
    """PuddleDuck sink (PuddleDuckStick)."""
    return create_sink_named(PUDDLE_DEVICE_NAME, PUDDLE_FIFO_PATH)


class ShadowingSink(BaseSink):
    """Fan-out sink that also feeds a ShadowEventController.

    This lets the server process (broadcast_state) observe the *same* evdev
    events it is publishing to clients (via uinput or FIFO) without opening the
    FIFO for reading.
    """

    def __init__(self, real_sink: BaseSink, shadow_ctrl, on_event=None):
        self._real = real_sink
        self._shadow = shadow_ctrl
        self._on_event = on_event

    def _feed_shadow(self, etype: int, code: int, value: int):
        if not self._shadow:
            return
        try:
            events = self._shadow.feed_evdev(etype, code, value)
        except Exception:
            return
        if not events:
            return
        if self._on_event:
            for ev in events:
                try:
                    self._on_event(ev)
                except Exception:
                    # Never let control hooks break the main loop.
                    pass

    def emit_abs(self, code, value):
        self._real.emit_abs(code, value)
        self._feed_shadow(EV_ABS, int(code), int(value))

    def emit_key(self, code, value):
        self._real.emit_key(code, value)
        self._feed_shadow(EV_KEY, int(code), int(value))

    def sync(self):
        self._real.sync()


def _parse_trigger(trigger):
    """Normalize a trigger spec into a comparable key."""
    if isinstance(trigger, int):
        return ("raw", int(trigger))

    if not isinstance(trigger, str):
        return None

    s = trigger.strip()
    if not s:
        return None

    if s.lower().startswith("kyberpad:"):
        tail = s.split(":", 1)[1].strip()
        if tail.isdigit():
            return ("raw", BTN_BASE + int(tail))
        return None

    if s.startswith("BTN") and s[3:].isdigit():
        return ("raw", int(s[3:]))

    # Bare integer string (raw button number)
    if s.isdigit():
        return ("raw", int(s))

    return ("name", s)


class ActionDispatcher:
    """Start/stop processes on controller button presses.

    Actions are configured in YAML.  The trigger table can be replaced at
    runtime without discarding process handles for actions that are already
    running; this lets the web editor update future button presses safely.
    """

    def __init__(self, actions: List[Dict[str, Any]]):
        self._by_trigger: Dict[Tuple[str, Any], List[Dict[str, Any]]] = {}
        self._procs: Dict[str, subprocess.Popen] = {}
        self._last_fire: Dict[str, float] = {}
        self._press_t0: Dict[Tuple[str, Any], float] = {}
        self.configure(actions)

    @staticmethod
    def read_yaml(path: str) -> List[Dict[str, Any]]:
        with open(path, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f) or {}
        if not isinstance(data, dict):
            raise ValueError("duck_actions.yaml root must be a mapping")
        actions = data.get("actions") or []
        if not isinstance(actions, list):
            raise ValueError("duck_actions.yaml 'actions' must be a list")
        return actions

    def configure(self, actions: List[Dict[str, Any]]) -> int:
        by_trigger: Dict[Tuple[str, Any], List[Dict[str, Any]]] = {}
        count = 0
        for raw in actions:
            if not isinstance(raw, dict):
                continue
            a = dict(raw)
            name = str(a.get("name") or "").strip()
            cmd = a.get("cmd")
            trig = _parse_trigger(a.get("trigger"))
            if not name or not cmd or trig is None:
                continue

            mode = str(a.get("mode") or "short").strip().lower()
            if mode not in ("short", "long"):
                mode = "short"
            a["mode"] = mode

            try:
                lps = float(a.get("long_press_s", 0.5))
            except Exception:
                lps = 0.5
            a["long_press_s"] = max(0.0, lps)
            a["toggle"] = bool(a.get("toggle", False))

            try:
                cooldown = float(a.get("cooldown_s", 0.25))
            except Exception:
                cooldown = 0.25
            a["cooldown_s"] = max(0.0, cooldown)

            by_trigger.setdefault(trig, []).append(a)
            count += 1

        self._by_trigger = by_trigger
        self._press_t0.clear()
        return count

    @classmethod
    def from_yaml(cls, path: str):
        return cls(cls.read_yaml(path))

    def reap(self):
        """Reap any processes that have exited."""
        dead = []
        for name, p in self._procs.items():
            if p.poll() is not None:
                dead.append(name)
        for name in dead:
            self._procs.pop(name, None)

    def _start(self, action: Dict[str, Any]):
        name = str(action.get("name"))
        cmd = action.get("cmd")
        cwd = action.get("cwd")
        env_over = action.get("env")

        if isinstance(cmd, str):
            cmd = cmd.split()
        if not isinstance(cmd, list) or not cmd:
            return

        env = os.environ.copy()
        if isinstance(env_over, dict):
            env.update({str(k): str(v) for k, v in env_over.items()})

        # Make child processes such as RLWalk/puddle_joy use the same fixed
        # virtual-controller FIFO path that broadcast_state created.
        env["PUDDLEDUCK_FIFO_DIR"] = FIFO_DIR
        env.setdefault("PYTHONUNBUFFERED", "1")

        try:
            p = subprocess.Popen(cmd, cwd=cwd, env=env)
            self._procs[name] = p
            print(f"[actions] started {name}: {cmd} (PUDDLEDUCK_FIFO_DIR={env.get('PUDDLEDUCK_FIFO_DIR')})", flush=True)
        except Exception as ex:
            print(f"[actions] failed to start {name}: {ex}")

    def _stop(self, action: Dict[str, Any]):
        name = str(action.get("name"))
        p = self._procs.get(name)
        if not p:
            return
        if p.poll() is not None:
            self._procs.pop(name, None)
            return

        sig_name = str(action.get("stop_signal") or "SIGINT").upper()
        sig = getattr(signal, sig_name, signal.SIGINT)
        try:
            p.send_signal(sig)
        except Exception:
            pass

        # Try a short wait to avoid zombies, but don't block the control loop long.
        try:
            p.wait(timeout=0.2)
        except Exception:
            pass

        if p.poll() is not None:
            self._procs.pop(name, None)
        print(f"[actions] stopped {name} ({sig_name})")

    def _cooldown_ok(self, action: Dict[str, Any]) -> bool:
        name = str(action.get("name"))
        cd = float(action.get("cooldown_s", 0.0))
        last = self._last_fire.get(name, 0.0)
        now = time.time()
        if now - last < cd:
            return False
        self._last_fire[name] = now
        return True

    def handle_event(self, ev):
        """Handle a puddle_joy.ControllerEvent."""
        try:
            is_button = bool(ev.event_type & 0x01)
        except Exception:
            return
        if not is_button:
            return

        pressed = bool(getattr(ev, "value", 0))

        keys = []
        # Name trigger
        name = getattr(ev, "name", None)
        if isinstance(name, str) and name:
            keys.append(("name", name))

        # Raw button number trigger
        number = getattr(ev, "number", None)
        if number is not None:
            try:
                keys.append(("raw", int(number)))
            except Exception:
                pass

        # Use one stable key for timing: prefer raw number if present, else name.
        timing_key = None
        number = getattr(ev, "number", None)
        name = getattr(ev, "name", None)
        if number is not None:
            try:
                timing_key = ("raw", int(number))
            except Exception:
                timing_key = None
        if timing_key is None and isinstance(name, str) and name:
            timing_key = ("name", name)

        now = time.time()
        if timing_key is not None and pressed:
            # record press time
            self._press_t0[timing_key] = now

        # We only fire actions on release (so we can classify short vs long).
        if not pressed:
            t0 = self._press_t0.pop(timing_key, None) if timing_key is not None else None
            if t0 is None:
                self.reap()
                return
            dt = now - t0

            for k in keys:
                for action in self._by_trigger.get(k, []):
                    want = action.get("mode", "short")
                    thresh = float(action.get("long_press_s", 0.5))
                    press_kind = "long" if dt > thresh else "short"
                    if want != press_kind:
                        continue
                    if not self._cooldown_ok(action):
                        continue

                    if bool(action.get("toggle", False)):
                        # toggle start/stop by action name
                        aname = str(action.get("name"))
                        p = self._procs.get(aname)
                        if p and p.poll() is None:
                            self._stop(action)
                        else:
                            self._start(action)
                    else:
                        # one-shot start
                        self._start(action)

        self.reap()


def play_warning_sound(level: str, voltage: Optional[float] = None) -> None:
    filename = SOUND_FILES.get(level)
    if not filename:
        print(f"[battery] Unknown warning level {level!r}")
        return

    path = os.path.join(SOUND_DIR, filename)
    if not os.path.exists(path):
        print(f"[battery] Sound file not found: {path}")
        return

    # Optional logging
    if voltage is not None:
        print(f"[battery] {level.upper()} warning at {voltage:.2f} V -> {path}")
    else:
        print(f"[battery] {level.upper()} warning -> {path}")

    try:
        # -q = quiet (no aplay banner).  Redirect stderr so early-boot audio
        # failures do not spam journal or obscure controller startup logs.
        subprocess.Popen(
            ["aplay", "-q", path],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
    except Exception as e:
        print(f"[battery] Failed to play sound via aplay: {e}", flush=True)


def _load_pushover_credentials() -> Optional[Tuple[str, str]]:
    """Return optional Pushover credentials, or None when disabled.

    Pushover is an opt-in feature. A missing directory, missing file,
    unreadable file, malformed INI, or incomplete [pushover] section all mean
    "disabled" and are intentionally silent.
    """
    if not PUSHOVER_CONFIG_PATH.parent.is_dir():
        return None
    if not PUSHOVER_CONFIG_PATH.is_file():
        return None

    config = configparser.ConfigParser(interpolation=None)
    try:
        with PUSHOVER_CONFIG_PATH.open("r", encoding="utf-8") as stream:
            config.read_file(stream)
        token = config.get("pushover", "token", fallback="").strip()
        user = config.get("pushover", "user", fallback="").strip()
    except Exception:
        return None

    if not token or not user:
        return None
    return token, user


def _send_pushover_notification_sync(
    token: str,
    user: str,
    title: str,
    message: str,
    *,
    priority: int = 0,
) -> None:
    payload = urlencode({
        "token": token,
        "user": user,
        "title": str(title),
        "message": str(message),
        "priority": str(int(priority)),
    }).encode("utf-8")
    request = Request(
        PUSHOVER_API_URL,
        data=payload,
        headers={
            "Content-Type": "application/x-www-form-urlencoded",
            "User-Agent": "PuddleDuck-battery-monitor/1.0",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=10.0) as response:
            response.read(4096)
        print(f"[battery] Pushover notification sent: {title}", flush=True)
    except HTTPError as ex:
        try:
            detail = ex.read(4096).decode("utf-8", errors="replace").strip()
        except Exception:
            detail = ""
        print(
            f"[battery] Pushover HTTP error {ex.code}"
            + (f": {detail}" if detail else ""),
            flush=True,
        )
    except (URLError, OSError) as ex:
        print(f"[battery] Pushover delivery failed: {ex}", flush=True)
    except Exception as ex:
        print(
            f"[battery] Unexpected Pushover error: {type(ex).__name__}: {ex}",
            flush=True,
        )


def send_pushover_notification(
    title: str,
    message: str,
    *,
    priority: int = 0,
) -> None:
    credentials = _load_pushover_credentials()
    if credentials is None:
        return

    token, user = credentials

    # Never block the 50 Hz state loop on DNS, TLS, or the Pushover service.
    threading.Thread(
        target=_send_pushover_notification_sync,
        args=(token, user, title, message),
        kwargs={"priority": int(priority)},
        name="puddleduck-pushover",
        daemon=True,
    ).start()


last_voltage_warning_time = 0.0
# 0 = normal/recovered, 1 = low notification attempted, 2 = critical attempted.
battery_notification_level = 0


def check_battery_and_warn(voltage: Optional[float]) -> None:
    global last_voltage_warning_time, battery_notification_level

    if voltage is None:
        return
    try:
        voltage = float(voltage)
    except (TypeError, ValueError):
        return
    if not math.isfinite(voltage):
        return

    hostname = socket.gethostname() or "PuddleDuck"

    # Reset only after a meaningful recovery, not from small voltage noise
    # around LOW_VOLTAGE. The next discharge can then notify again.
    if voltage >= BATTERY_NOTIFICATION_RESET_VOLTAGE:
        if battery_notification_level:
            print(
                f"[battery] Voltage recovered to {voltage:.2f} V; "
                "Pushover warning state reset",
                flush=True,
            )
        battery_notification_level = 0

    # Pushover is edge-triggered: once for low, then once more for critical.
    if voltage <= CRITICAL_VOLTAGE and battery_notification_level < 2:
        battery_notification_level = 2
        send_pushover_notification(
            title=f"{hostname} battery critical",
            message=(
                f"Battery voltage is {voltage:.2f} V, at or below the "
                f"{CRITICAL_VOLTAGE:.2f} V critical threshold."
            ),
            priority=1,
        )
    elif voltage <= LOW_VOLTAGE and battery_notification_level < 1:
        battery_notification_level = 1
        send_pushover_notification(
            title=f"{hostname} battery low",
            message=(
                f"Battery voltage is {voltage:.2f} V, at or below the "
                f"{LOW_VOLTAGE:.2f} V low threshold."
            ),
            priority=0,
        )

    # Keep the existing local sounds periodic and independent of Pushover.
    now = time.time()
    if (now - last_voltage_warning_time) < WARNING_INTERVAL:
        return

    if voltage <= CRITICAL_VOLTAGE:
        last_voltage_warning_time = now
        play_warning_sound(level="critical", voltage=voltage)
    elif voltage <= LOW_VOLTAGE:
        last_voltage_warning_time = now
        play_warning_sound(level="low", voltage=voltage)

def get_bms_voltage_from_state(state):
    for sensor in state.get("sensors", []):
        if isinstance(sensor, dict) and sensor.get("name") == "bms":
            return sensor.get("voltage", None)
    return None


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x

def _norm(x: float, lo: float, hi: float) -> float:
    if hi == lo:
        return 0.0
    return _clamp01((x - lo) / (hi - lo))

def _bms_temp_f_from_sensor(bms: dict):
    # Try common keys; returns Fahrenheit or None.
    if not isinstance(bms, dict):
        return None
    for k in ("temp_f", "temperature_f", "tempF", "temperatureF"):
        if k in bms and isinstance(bms.get(k), (int, float)):
            return float(bms[k])
    for k in ("temp", "temperature", "temp_c", "temperature_c", "tempC", "temperatureC"):
        v = bms.get(k)
        if isinstance(v, (int, float)):
            v = float(v)
            # Heuristic: values <= 45 are likely Celsius; convert to F.
            return v * 9.0/5.0 + 32.0 if v <= 45.0 else v
    return None

def _read_wifi_norm_linux() -> float:
    # Best-effort, cheap: parse /proc/net/wireless (quality is 0..70 usually)
    try:
        with open("/proc/net/wireless", "r", encoding="utf-8") as f:
            lines = f.read().splitlines()
        for line in lines[2:]:
            if ":" not in line:
                continue
            # iface: status link level noise ...
            parts = line.replace(":", " ").split()
            if len(parts) < 4:
                continue
            link = float(parts[2])  # "link" quality
            # Normalize 0..70 -> 0..1 (common)
            return _clamp01(link / 70.0)
    except Exception:
        pass
    # Fallback: try `iwconfig` (slower)
    try:
        out = subprocess.check_output(["iwconfig"], stderr=subprocess.STDOUT, text=True, timeout=0.3)
        # look for "Link Quality=xx/yy"
        m = re.search(r"Link Quality=(\d+)/(\d+)", out)
        if m:
            num = float(m.group(1)); den = float(m.group(2))
            if den > 0:
                return _clamp01(num / den)
    except Exception:
        pass
    return 0.0

_audio_debug_state = {"reported": False}


def _audio_runtime_dir() -> Optional[str]:
    d = os.environ.get("XDG_RUNTIME_DIR")
    if d and os.path.isdir(d):
        return d
    uid_dir = f"/run/user/{os.getuid()}"
    if os.path.isdir(uid_dir):
        return uid_dir
    return None


def _audio_env() -> Dict[str, str]:
    env = os.environ.copy()
    d = _audio_runtime_dir()
    if d:
        env.setdefault("XDG_RUNTIME_DIR", d)
        bus = os.path.join(d, "bus")
        if os.path.exists(bus):
            env.setdefault("DBUS_SESSION_BUS_ADDRESS", f"unix:path={bus}")
        pulse = os.path.join(d, "pulse", "native")
        if os.path.exists(pulse):
            env.setdefault("PULSE_SERVER", f"unix:{pulse}")
    return env


def _pulse_socket_ready() -> bool:
    d = _audio_runtime_dir()
    if not d:
        return False
    return os.path.exists(os.path.join(d, "pulse", "native"))


def _alsa_controls() -> List[str]:
    # Use a comma-separated override if this machine's mixer control has a
    # different name.  Common Jetson/ALSA names include Master, Speaker, PCM,
    # and Headphone.
    raw = (
        os.environ.get("PUDDLEDUCK_ALSA_CONTROLS")
        or os.environ.get("PUDDLEDUCK_ALSA_MIXER")
        or "Master,Speaker,PCM,Headphone"
    )
    return [x.strip() for x in raw.split(",") if x.strip()]


def _amixer_cmd(*args: str, quiet: bool = False) -> List[str]:
    cmd = ["amixer"]
    card = os.environ.get("PUDDLEDUCK_ALSA_CARD", "").strip()
    if card:
        cmd.extend(["-c", card])
    if quiet:
        cmd.append("-q")
    # Mapped mode makes percentages closer to what users expect for controls
    # with non-linear dB ranges, but still works for simple integer controls.
    cmd.append("-M")
    cmd.extend(str(a) for a in args)
    return cmd


def _parse_amixer_volume_norm(text: str) -> Optional[float]:
    vals = []
    for m in re.finditer(r"\[(\d{1,3})%\]", text or ""):
        try:
            vals.append(max(0.0, min(100.0, float(m.group(1)))))
        except Exception:
            pass
    if not vals:
        return None
    # Stereo controls usually print duplicate L/R percentages.  Average them so
    # asymmetric channels still produce a sensible single value for OSC.
    return _clamp01((sum(vals) / len(vals)) / 100.0)


def _get_alsa_volume_norm() -> Optional[float]:
    if shutil.which("amixer") is None:
        return None
    for ctl in _alsa_controls():
        try:
            out = subprocess.check_output(
                _amixer_cmd("sget", ctl),
                text=True,
                timeout=0.4,
                stderr=subprocess.DEVNULL,
            )
            v = _parse_amixer_volume_norm(out)
            if v is not None:
                return v
        except Exception:
            continue
    return None


def _set_alsa_volume_norm(v: float) -> bool:
    if shutil.which("amixer") is None:
        return False
    pct = int(round(_clamp01(float(v)) * 100.0))
    for ctl in _alsa_controls():
        try:
            subprocess.check_call(
                _amixer_cmd("sset", ctl, f"{pct}%", quiet=True),
                timeout=0.5,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return True
        except Exception:
            continue
    return False


def _get_pulse_volume_norm() -> Optional[float]:
    # Optional debug/login-session fallback.  Never call pactl unless the Pulse
    # compatibility socket exists; otherwise it prints pa_context_connect()
    # failures and the robot can boot before /run/user/$uid exists.
    if not _pulse_socket_ready() or shutil.which("pactl") is None:
        return None
    try:
        out = subprocess.check_output(
            ["pactl", "get-sink-volume", "@DEFAULT_SINK@"],
            text=True,
            timeout=0.4,
            stderr=subprocess.DEVNULL,
            env=_audio_env(),
        )
        m = re.search(r"(\d+)%", out)
        if m:
            return _clamp01(float(m.group(1)) / 100.0)
    except Exception:
        pass
    return None


def _set_pulse_volume_norm(v: float) -> bool:
    if not _pulse_socket_ready() or shutil.which("pactl") is None:
        return False
    pct = int(round(_clamp01(float(v)) * 100.0))
    try:
        subprocess.check_call(
            ["pactl", "set-sink-volume", "@DEFAULT_SINK@", f"{pct}%"],
            timeout=0.5,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            env=_audio_env(),
        )
        return True
    except Exception:
        return False


def _audio_debug_once() -> None:
    if _audio_debug_state["reported"]:
        return
    _audio_debug_state["reported"] = True
    d = _audio_runtime_dir()
    print(
        f"[audio] backend=alsa-first amixer={bool(shutil.which('amixer'))} "
        f"alsa_card={os.environ.get('PUDDLEDUCK_ALSA_CARD', '')!r} "
        f"alsa_controls={','.join(_alsa_controls())!r} "
        f"runtime_dir={d!r} pulse_ready={_pulse_socket_ready()} "
        f"pulse={os.path.exists(os.path.join(d, 'pulse', 'native')) if d else False} "
        f"pipewire={os.path.exists(os.path.join(d, 'pipewire-0')) if d else False} "
        f"XDG_RUNTIME_DIR={os.environ.get('XDG_RUNTIME_DIR')!r}",
        flush=True,
    )


def _get_system_volume_norm_optional() -> Optional[float]:
    _audio_debug_once()

    # Normal robot boot path: ALSA does not require /run/user/$uid, user D-Bus,
    # PulseAudio, PipeWire, or an interactive login.
    v = _get_alsa_volume_norm()
    if v is not None:
        return v

    # Optional fallback for debugging sessions where ALSA controls are not
    # exposed but Pulse/PipeWire is already running.
    return _get_pulse_volume_norm()


def _get_system_volume_norm() -> float:
    value = _get_system_volume_norm_optional()
    return 0.0 if value is None else float(value)


def _set_system_volume_norm(v: float) -> bool:
    v = _clamp01(float(v))

    # Prefer ALSA for deterministic headless behavior.  If no ALSA mixer exists,
    # use the login-session Pulse/PipeWire path when available.
    if _set_alsa_volume_norm(v):
        return True
    if _set_pulse_volume_norm(v):
        return True

    pct = int(round(v * 100.0))
    print(f"[audio] no available ALSA/Pulse mixer for volume set to {pct}%", flush=True)
    return False

# ---------------------------------------------------------------------
# UDP broadcast helper
# ---------------------------------------------------------------------

class UdpBroadcastSender:
    """Best-effort UDP sender for one target.

    This object is now used from a background worker thread only.  The main
    /dev/puddleduck_ops loop publishes the newest encoded JSON frame to a
    latest-only worker queue, so slow DNS, ARP, Wi-Fi, or route failures cannot
    stall joystick/FIFO processing.
    """

    def __init__(self, broadcast_address: str, port: int, retry_interval: float = BROADCAST_RETRY_INTERVAL):
        self.addr = (str(broadcast_address), int(port))
        self.retry_interval = max(0.1, float(retry_interval))
        self.sock: Optional[socket.socket] = None
        self.next_retry_at = 0.0
        self._was_unavailable = False

        print(f"[broadcast] UDP target {self.addr}; retry_interval={self.retry_interval:.1f}s")

    def close(self) -> None:
        sock = self.sock
        self.sock = None
        if sock is not None:
            try:
                sock.close()
            except Exception:
                pass

    def _mark_unavailable(self, phase: str, ex: BaseException) -> None:
        self.close()
        self._was_unavailable = True
        self.next_retry_at = time.monotonic() + self.retry_interval
        print(
            f"[broadcast] {phase} failed for {self.addr}: {ex}; "
            f"will retry in {self.retry_interval:.0f}s",
            flush=True,
        )

    def _connect(self) -> bool:
        self.close()
        sock = None
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
            # Keep send failures local to this target.  This timeout does not
            # bound hostname resolution, but resolution now happens off the
            # control/state loop in AsyncUdpStateWorker.
            try:
                sock.settimeout(0.25)
            except Exception:
                pass
            sock.connect(self.addr)
            try:
                sock.setblocking(False)
            except Exception:
                pass
        except OSError as ex:
            if sock is not None:
                try:
                    sock.close()
                except Exception:
                    pass
            self._mark_unavailable("connect", ex)
            return False

        self.sock = sock
        self.next_retry_at = 0.0
        if self._was_unavailable:
            print(f"[broadcast] UDP target reachable again: {self.addr}", flush=True)
        else:
            print(f"[broadcast] UDP broadcast ready on {self.addr}", flush=True)
        self._was_unavailable = False
        return True

    def send_payload(self, payload: bytes) -> bool:
        now = time.monotonic()
        if self.sock is None:
            if now < self.next_retry_at:
                return False
            if not self._connect():
                return False

        try:
            self.sock.send(payload)
            return True
        except (BlockingIOError, InterruptedError):
            # Non-blocking socket could not accept a datagram right now.  Drop
            # this frame; the async worker keeps only the newest state anyway.
            return False
        except OSError as ex:
            self._mark_unavailable("send", ex)
            return False

    def send_state(self, state: Dict[str, Any]) -> bool:
        try:
            payload = json.dumps(state).encode("utf-8")
        except Exception:
            return False
        return self.send_payload(payload)


def _trace_enabled(name: str, default: bool = True) -> bool:
    raw = os.environ.get(name)
    if raw is None:
        return bool(default)
    return str(raw).strip().lower() not in ("0", "false", "no", "off")


def _env_float(name: str, default: float) -> float:
    try:
        return float(os.environ.get(name, default))
    except Exception:
        return float(default)


def _env_int(name: str, default: int) -> int:
    try:
        return int(os.environ.get(name, default))
    except Exception:
        return int(default)


class AsyncUdpStateWorker:
    """Latest-only background sender for one UDP target."""

    def __init__(self, addr: str, port: int, *, retry_interval: float):
        self.addr = str(addr)
        self.port = int(port)
        self.sender = UdpBroadcastSender(self.addr, self.port, retry_interval=retry_interval)
        self._cv = threading.Condition()
        self._pending: Optional[Tuple[int, bytes, float, int]] = None
        self._closed = False
        self._published = 0
        self._replaced = 0
        self._sent = 0
        self._send_fail = 0
        self._max_send_ms = 0.0
        self._max_age_ms = 0.0
        self._last_send_ms = 0.0
        self._last_age_ms = 0.0
        self._last_seq = 0
        self._last_trace_t = 0.0
        self._trace = _trace_enabled("PUDDLEDUCK_UDP_TRACE", True)
        self._trace_interval = max(0.25, _env_float("PUDDLEDUCK_UDP_TRACE_INTERVAL", 2.0))
        self._warn_ms = max(1.0, _env_float("PUDDLEDUCK_UDP_WARN_MS", 25.0))
        self._age_warn_ms = max(10.0, _env_float("PUDDLEDUCK_UDP_AGE_WARN_MS", 250.0))
        self._thread = threading.Thread(
            target=self._run,
            name=f"udp-state-{self.addr}:{self.port}",
            daemon=True,
        )
        self._thread.start()

    def publish_payload(self, seq: int, payload: bytes, publish_t: float, publish_wall_ms: int) -> None:
        with self._cv:
            if self._pending is not None:
                # The previous frame was not sent yet.  Replace it so a slow
                # target never creates seconds of stale telemetry backlog.
                self._replaced += 1
            self._pending = (int(seq), bytes(payload), float(publish_t), int(publish_wall_ms))
            self._published += 1
            self._cv.notify()

    def _pop(self) -> Optional[Tuple[int, bytes, float, int]]:
        with self._cv:
            while self._pending is None and not self._closed:
                self._cv.wait(timeout=self._trace_interval)
            if self._closed:
                return None
            item = self._pending
            self._pending = None
            return item

    def _maybe_trace(self, reason: str) -> None:
        if not self._trace:
            return
        now = time.monotonic()
        if reason == "periodic" and (now - self._last_trace_t) < self._trace_interval:
            return
        self._last_trace_t = now
        pending = 0
        with self._cv:
            pending = 1 if self._pending is not None else 0
            published = self._published
            replaced = self._replaced
        print(
            "UDP_TRACE "
            f"reason={reason} target={self.addr}:{self.port} "
            f"published={published} sent={self._sent} replaced={replaced} "
            f"send_fail={self._send_fail} pending={pending} last_seq={self._last_seq} "
            f"last_send_ms={self._last_send_ms:.3f} max_send_ms={self._max_send_ms:.3f} "
            f"last_age_ms={self._last_age_ms:.1f} max_age_ms={self._max_age_ms:.1f}",
            flush=True,
        )

    def _run(self) -> None:
        while True:
            item = self._pop()
            if item is None:
                return
            seq, payload, publish_t, _publish_wall_ms = item
            age_ms = max(0.0, (time.monotonic() - publish_t) * 1000.0)
            t0 = time.monotonic()
            ok = False
            try:
                ok = self.sender.send_payload(payload)
            except Exception as ex:
                self._send_fail += 1
                print(f"UDP_TRACE reason=exception target={self.addr}:{self.port} error={ex!r}", flush=True)
                continue
            finally:
                send_ms = (time.monotonic() - t0) * 1000.0
                self._last_send_ms = send_ms
                self._max_send_ms = max(self._max_send_ms, send_ms)
                self._last_age_ms = age_ms
                self._max_age_ms = max(self._max_age_ms, age_ms)
                self._last_seq = int(seq)

            if ok:
                self._sent += 1
            else:
                self._send_fail += 1

            if send_ms >= self._warn_ms:
                self._maybe_trace("slow_send")
            elif age_ms >= self._age_warn_ms:
                self._maybe_trace("stale_send")
            else:
                self._maybe_trace("periodic")


class ActionDispatcherManager:
    """Thread-safe, live-reloadable owner for duck_actions.yaml."""

    def __init__(self, path: Optional[str]):
        self.path = os.path.expanduser(str(path or "~/duck_actions.yaml"))
        self._lock = threading.RLock()
        self._dispatcher = ActionDispatcher([])
        self._last_error = ""
        self._loaded = 0
        self.reload()

    def reload(self) -> Dict[str, Any]:
        with self._lock:
            try:
                if not self.path or not os.path.isfile(self.path):
                    self._loaded = self._dispatcher.configure([])
                    self._last_error = ""
                    return {
                        "ok": True,
                        "path": self.path,
                        "loaded": 0,
                        "message": "actions file is absent; no controller actions are configured",
                    }
                actions = ActionDispatcher.read_yaml(self.path)
                self._loaded = self._dispatcher.configure(actions)
                self._last_error = ""
                print(f"[actions] Loaded {self._loaded} action(s) from {self.path}", flush=True)
                return {
                    "ok": True,
                    "path": self.path,
                    "loaded": self._loaded,
                    "message": f"loaded {self._loaded} action(s)",
                }
            except Exception as ex:
                self._last_error = f"{type(ex).__name__}: {ex}"
                print(f"[actions] Failed to load actions YAML {self.path}: {ex}", flush=True)
                return {
                    "ok": False,
                    "path": self.path,
                    "loaded": self._loaded,
                    "message": self._last_error,
                }

    def status(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "ok": not bool(self._last_error),
                "path": self.path,
                "loaded": int(self._loaded),
                "message": self._last_error or f"loaded {self._loaded} action(s)",
            }

    def handle_event(self, ev) -> None:
        with self._lock:
            self._dispatcher.handle_event(ev)


class AsyncUdpJsonBroadcaster:
    """Async latest-only JSON fanout for robot state packets."""

    def __init__(self, targets: List[Tuple[str, int]], *, retry_interval: float):
        self._workers = [
            AsyncUdpStateWorker(addr, udp_port, retry_interval=retry_interval)
            for addr, udp_port in (targets or [])
        ]
        self._seq = 0
        self._trace = _trace_enabled("PUDDLEDUCK_STATE_TRACE", True)
        self._warn_ms = max(1.0, _env_float("PUDDLEDUCK_STATE_PUBLISH_WARN_MS", 10.0))
        print(
            f"[broadcast] async latest-only UDP fanout targets={len(self._workers)}",
            flush=True,
        )

    @property
    def seq(self) -> int:
        return int(self._seq)

    def publish(self, state: Dict[str, Any]) -> bool:
        if not self._workers:
            return False
        t0 = time.monotonic()
        wall_ms = int(time.time() * 1000)
        self._seq += 1
        seq = int(self._seq)
        try:
            # Add send-side timing to the UDP payload only.  Do not mutate the
            # main state dict used by OSC/control code.
            out_state = dict(state)
            out_state["_broadcast"] = {
                "seq": seq,
                "t_ms": wall_ms,
                "source": "broadcast_state",
            }
            payload = json.dumps(out_state, separators=(",", ":")).encode("utf-8")
        except Exception as ex:
            print(f"STATE_LOOP_TRACE reason=json_encode_error seq={seq} error={ex!r}", flush=True)
            return False

        publish_t = time.monotonic()
        for worker in self._workers:
            worker.publish_payload(seq, payload, publish_t, wall_ms)
        publish_ms = (time.monotonic() - t0) * 1000.0
        if self._trace and publish_ms >= self._warn_ms:
            print(
                f"STATE_LOOP_TRACE reason=slow_publish seq={seq} "
                f"publish_ms={publish_ms:.3f} bytes={len(payload)} targets={len(self._workers)}",
                flush=True,
            )
        return True

def _parse_udp_target(target: str, default_port: int) -> Tuple[str, int]:
    """Parse HOST or HOST:PORT into a UDP destination tuple.

    This intentionally handles IPv4/hostname targets only; that matches the
    robot network use case here and keeps command-line parsing unambiguous.
    """
    text = str(target or "").strip()
    if not text:
        raise ValueError("empty UDP target")

    host = text
    port = int(default_port)

    # Allow the convenient form 192.168.50.3:5005 or bdx-head.local:5005.
    # Avoid trying to parse IPv6 literals as HOST:PORT.
    if text.count(":") == 1:
        maybe_host, maybe_port = text.rsplit(":", 1)
        if maybe_host and maybe_port:
            host = maybe_host.strip()
            port = int(maybe_port.strip())

    if not host:
        raise ValueError(f"invalid UDP target: {target!r}")
    if port <= 0 or port > 65535:
        raise ValueError(f"invalid UDP port in target {target!r}: {port}")
    return host, port


def _udp_target_enabled(text: Optional[str]) -> bool:
    """Return False for explicit off/none/empty target values."""
    if text is None:
        return False
    value = str(text).strip().lower()
    return bool(value) and value not in ("0", "false", "no", "none", "off", "disabled")


def _dedupe_udp_targets(targets: List[Tuple[str, int]]) -> List[Tuple[str, int]]:
    """De-duplicate UDP targets while preserving order."""
    seen = set()
    out: List[Tuple[str, int]] = []
    for target in targets:
        if target in seen:
            continue
        seen.add(target)
        out.append(target)
    return out


def _build_udp_target_list(
    *,
    head_udp_target: Optional[str],
    port: int,
    viewer_broadcast: bool = False,
    viewer_broadcast_address: str = DEFAULT_VIEWER_BROADCAST_ADDRESS,
    viewer_udp_targets: Optional[List[str]] = None,
) -> List[Tuple[str, int]]:
    """Return required body->head target plus optional Viewer targets.

    The wired head link is the normal robot telemetry path, so it is first and
    enabled by default.  Desktop Viewer traffic is opt-in so Wi-Fi or broadcast
    state cannot affect normal robot operation.
    """
    targets: List[Tuple[str, int]] = []

    if _udp_target_enabled(head_udp_target):
        targets.append(_parse_udp_target(str(head_udp_target), int(port)))

    if bool(viewer_broadcast):
        targets.append((str(viewer_broadcast_address), int(port)))

    for raw in (viewer_udp_targets or []):
        targets.append(_parse_udp_target(raw, int(port)))

    return _dedupe_udp_targets(targets)




